// ---------------------------------------------------------------------
// Simple pattern scanner used to resolve offsets by AOB (array-of-bytes)
// signature instead of hardcoding them. Pattern format example:
//   "48 8B ?? ?? 89 45"   ("??" = wildcard byte)
// Returns the RELATIVE offset (from the library base) as a hex string,
// or "Not Found" if the pattern does not match anywhere in the module.
// ---------------------------------------------------------------------
struct ModuleRange { uintptr_t start; uintptr_t end; };

ModuleRange getModuleRange(const char *libraryName) {
    ModuleRange range = {0, 0};
    char line[512] = {0};
    FILE *fp = fopen(OBFUSCATE("/proc/self/maps"), OBFUSCATE("rt"));
    if (!fp) return range;

    while (fgets(line, sizeof(line), fp)) {
        if (strstr(line, libraryName)) {
            uintptr_t segStart = 0, segEnd = 0;
            sscanf(line, "%lx-%lx", &segStart, &segEnd);
            if (range.start == 0 || segStart < range.start) range.start = segStart;
            if (segEnd > range.end) range.end = segEnd;
        }
    }
    fclose(fp);
    return range;
}

std::vector<int> parsePattern(const char *pattern) {
    std::vector<int> bytes;
    std::string p(pattern);
    std::stringstream ss(p);
    std::string byteStr;
    while (ss >> byteStr) {
        if (byteStr == "??" || byteStr == "?") {
            bytes.push_back(-1); // wildcard
        } else {
            bytes.push_back((int) strtol(byteStr.c_str(), nullptr, 16));
        }
    }
    return bytes;
}

std::string findPatternOffset(const char *libraryName, const char *pattern) {
    ModuleRange range = getModuleRange(libraryName);
    if (range.start == 0 || range.end <= range.start)
        return OBFUSCATE("Not Found");

    std::vector<int> needle = parsePattern(pattern);
    if (needle.empty())
        return OBFUSCATE("Not Found");

    size_t needleLen = needle.size();
    uint8_t *data = reinterpret_cast<uint8_t *>(range.start);
    size_t regionLen = range.end - range.start;

    for (size_t i = 0; i + needleLen <= regionLen; i++) {
        bool match = true;
        for (size_t j = 0; j < needleLen; j++) {
            if (needle[j] != -1 && data[i + j] != (uint8_t) needle[j]) {
                match = false;
                break;
            }
        }
        if (match) {
            char hexOffset[32];
            snprintf(hexOffset, sizeof(hexOffset), "%lx", (unsigned long) i);
            return std::string(hexOffset);
        }
    }
    return OBFUSCATE("Not Found");
}

