// ---------------------------------------------------------------------
// Feature list shown in the main "Search Mods" screen. Numeric IDs here
// are what Preferences.Changes() receives when a toggle/button/seekbar
// is used — read them in your hook code to know which mod was toggled.
// ---------------------------------------------------------------------
jobjectArray GetFeatureList(JNIEnv *env, jobject thiz) {
    jobjectArray ret;

    const char *features[] = {
            OBFUSCATE("Category_Search Mods"),
            OBFUSCATE("10_Button_Search All Mods"),
            OBFUSCATE("Category_See Offsets"),
            OBFUSCATE("20_Button_Show Offsets"),
    };

    int Total_Feature = (sizeof features / sizeof features[0]);
    ret = (jobjectArray)
            env->NewObjectArray(Total_Feature, env->FindClass(OBFUSCATE("java/lang/String")),
                                env->NewStringUTF(""));
    for (int i = 0; i < Total_Feature; i++)
        env->SetObjectArrayElement(ret, i, env->NewStringUTF(features[i]));

    return (ret);
}

jobjectArray SettingsList(JNIEnv *env, jobject activityObject) {
    jobjectArray ret;

    const char *features[] = {
            OBFUSCATE("Category_Settings"),
            OBFUSCATE("-1_Toggle_Save feature preferences"), //-1 is checked on Preferences.java
          //  OBFUSCATE("-3_Toggle_Auto size vertically"),
            OBFUSCATE("Category_Menu"),
            OBFUSCATE("-7_SeekBar_Icon Opacity_1_10"),   // controls ICON_ALPHA
            OBFUSCATE("-8_SeekBar_Icon Size_10_100"),     // controls icon width/height
            OBFUSCATE("-9_Button_Hide Icon"),
    };

    int Total_Feature = (sizeof features /
                         sizeof features[0]); //Now you dont have to manually update the number everytime;
    ret = (jobjectArray)
            env->NewObjectArray(Total_Feature, env->FindClass(OBFUSCATE("java/lang/String")),
                                env->NewStringUTF(""));
    int i;
    for (i = 0; i < Total_Feature; i++)
        env->SetObjectArrayElement(ret, i, env->NewStringUTF(features[i]));

    settingsValid = true;

    return (ret);
}
